      try {
        await client.fleets.getCharacterFleetInfo(characterId);
      } catch (error) {
        caughtError = error;
      }
    });

    then('the client shall throw an EsiError with status 404', () => {
      expect(caughtError).toBeInstanceOf(EsiError);
    });
