  test('WHEN getFleetInformation is called, the client shall return the fleet MOTD, boss, and settings', ({ given, when, then }) => {
    let result: any;
    const fleetId = 1234567890;

    given('a valid fleet ID is provided', () => {
      const mockFleet = TestDataFactory.createFleetInfo({
        fleet_id: fleetId,
        motd: 'Form up on titan',
        is_free_move: false,
      });

      jest
        .spyOn(client.fleets, 'getFleetInformation')
        .mockResolvedValue(mockFleet);
    });

